{
  "root": "main",
  "state": {
    "laptops": [
      { "Option": "A", "Screen": "13.6-inch", "RAM": "16 GB", "Storage": "512 GB", "Price": "€1,050", "Weight": "1.2 kg", "Best For": "Maximum portability" },
      { "Option": "B", "Screen": "14-inch", "RAM": "16 GB", "Storage": "1 TB", "Price": "€1,180", "Weight": "1.5 kg", "Best For": "Best overall balance" },
      { "Option": "C", "Screen": "14-inch", "RAM": "32 GB", "Storage": "512 GB", "Price": "€1,240", "Weight": "1.6 kg", "Best For": "Heavier multitasking" }
    ]
  },
  "elements": {
    "main": { "type": "Stack", "props": { "direction": "vertical", "gap": "md", "padding": 16 }, "children": ["title", "summary", "comparison", "why_b", "actions", "sources"] },
    "title": { "type": "Text", "props": { "text": "Graduate Laptop Fit for Berlin", "variant": "h1" }, "children": [] },
    "summary": { "type": "Text", "props": { "text": "For coding, writing, and light photo editing, Option B is the best balance. It stays within budget, matches the preferred 14-inch size, and provides the most storage.", "variant": "body" }, "children": [] },
    "comparison": { "type": "Table", "props": { "statePath": "/laptops", "domain": "comparison", "preferredPresentation": "cards", "primaryColumn": "Option", "columns": [{ "key": "Option", "label": "Option" }, { "key": "Screen", "label": "Screen" }, { "key": "RAM", "label": "RAM" }, { "key": "Storage", "label": "Storage" }, { "key": "Price", "label": "Price" }, { "key": "Weight", "label": "Weight" }, { "key": "Best For", "label": "Best For" }] }, "children": [] },
    "why_b": { "type": "Stack", "props": { "direction": "vertical", "gap": "sm" }, "children": ["why_b_title", "why_b_text"] },
    "why_b_title": { "type": "Text", "props": { "text": "Why Option B is the best pick", "variant": "h2" }, "children": [] },
    "why_b_text": { "type": "Text", "props": { "text": "It fits the budget, provides a 14-inch display, 1 TB SSD for projects, 16 GB RAM for multitasking, and a portable 1.5 kg weight.", "variant": "body" }, "children": [] },
    "actions": { "type": "Stack", "props": { "direction": "horizontal", "gap": "md" }, "children": ["btn1", "btn2"] },
    "btn1": { "type": "Button", "props": { "label": "Compare by priority" }, "on": { "press": { "action": "openUrl", "params": { "url": "https://www.notebookcheck.net/" } } }, "children": [] },
    "btn2": { "type": "Button", "props": { "label": "Check Berlin prices" }, "on": { "press": { "action": "openUrl", "params": { "url": "https://www.idealo.de/" } } }, "children": [] },
    "sources": { "type": "Stack", "props": { "direction": "vertical", "gap": "sm" }, "children": ["src_title", "src1", "src2"] },
    "src_title": { "type": "Text", "props": { "text": "Sources", "variant": "h3" }, "children": [] },
    "src1": { "type": "Button", "props": { "label": "Notebookcheck reviews", "variant": "borderless" }, "on": { "press": { "action": "openUrl", "params": { "url": "https://www.notebookcheck.net/" } } }, "children": [] },
    "src2": { "type": "Button", "props": { "label": "Idealo price comparison", "variant": "borderless" }, "on": { "press": { "action": "openUrl", "params": { "url": "https://www.idealo.de/" } } }, "children": [] }
  }
}
